    r.content

return r

def _decode(
    self,
    data: bytes,
    decode_content: bool | None,
    flush_decoder: bool,
    max_length: int | None = None,
) -> bytes:
    """
    Decode the data passed in and potentially flush the decoder.
    """
    if not decode_content:
        if self._has_decoded_content:
            raise RuntimeError(
                "Calling read(decode_content=False) is not supported after "
                "read(decode_content=True) was called."
            )
        return data

    if max_length is None or flush_decoder:
        max_length = -1

    try:
        if self._decoder:
            data = self._decoder.decompress(data, max_length=max_length)
            self._has_decoded_content = True
    except self.DECODER_ERROR_CLASSES as e:
        content_encoding = self.headers.get("content-encoding", "").lower()
        raise DecodeError(
            "Received response with content-encoding: %s, but "
            "failed to decode it." % content_encoding,
            e,
        ) from e
    if flush_decoder:
        data += self._flush_decoder()

    return data

def _flush_decoder(self) -> bytes:
    """
    Flushes the decoder. Should only be called if the decoder is actually
    being used.
    """
    if self._decoder:
        return self._decoder.decompress(b"") + self._decoder.flush()

"""
Catch low-level python exceptions, instead re-raising urllib3
variants, so that low-level exceptions are not leaked in the
high-level api.

On exit, release the connection back to the pool.
"""
clean_exit = False

try:
    try:
        yield

    except SocketTimeout as e:
        # FIXME: Ideally we'd like to include the url in the ReadTimeoutError but
        # there is yet no clean way to get at it from this context.
        raise ReadTimeoutError(self._pool, None, "Read timed out.") from e  # type: ignore[arg-type]

    except BaseSSLError as e:
        # SSL errors related to framing/MAC get wrapped and reraised here
        raise SSLError(e) from e

    except IncompleteRead as e:
        if (
            e.expected is not None
            and e.partial is not None
            and e.expected == -e.partial
        ):
            arg = "Response may not contain content."
        else:
            arg = f"Connection broken: {e!r}"
        raise ProtocolError(arg, e) from e

    except (HTTPException, OSError) as e:
        raise ProtocolError(f"Connection broken: {e!r}", e) from e

    elif read1:
        return self._fp.read1(amt) if amt is not None else self._fp.read1()
    else:
        # StringIO doesn't like amt=None
        return self._fp.read(amt) if amt is not None else self._fp.read()

